import React from 'react'
import StepsWrapper from './index.style'
import { mergeClassNames } from '../../helpers/css'

const PolicyStepsHeader = ({ activeCount, stepsData = [], prevActive = [] }) => {
  return (
    <StepsWrapper>
      <div className="steps-inner">
        <ul className="steps__container">
          {stepsData.map((step) => {
            return (
              <li
                key={step.index}
                className={mergeClassNames(
                  'steps__list',
                  activeCount === step.index && 'steps__list--active',
                  prevActive[step.index] ? 'steps__list--prev' : ''
                )}
              >
                <div
                  className={mergeClassNames(
                    'steps__list__count',
                    prevActive[step.index] ? 'steps__list__count--prev' : ''
                  )}
                >
                  {prevActive[step.index] ? '' : step.index}
                </div>
                <div className="steps__list__content">{step.text}</div>
              </li>
            )
          })}
        </ul>
      </div>
    </StepsWrapper>
  )
}

export default PolicyStepsHeader
