import { useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import {
  useCompleteDraftQuote,
  useGetDraftQuoteDetails,
  useUpdateDraftQuote,
} from '../../../state/hooks/usePolicyState'
import Tabs from '../../../../../../components/Tabs'
import { Container } from '../../../../../../components'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import MvPaymentInfo from '../../../../../../components/MvPaymentInfo'
import { ERROR_LANG } from '../../../../../../lang'
import PackageItem from '../../../../Application/components/PackageItem'
import { POLICY_STEPS } from '../../../constants'
import { POLICY_TABS } from '../constants'
import ShareQuotation from '../../MVPolicyQuotationPopup'
import TabInsuranceDetail from '../components/TabInsuranceDetail'
import TabInsuredDetail from '../components/TabInsuredDetail'
import TabPolicyDetail from '../components/TabPolicyDetail'
import PopupDisclaimer from '../components/PopupDisclaimer'
import { ConfirmationStyle } from './index.style'

function MVPolicyConfirmationContainer() {
  const history = useHistory()
  const { id } = useParams()

  const [activeTab, setActiveTab] = useState(POLICY_TABS[0])
  const [showPopupDisclaimer, setShowPopupDisclaimer] = useState(false)
  const [showShareSheet, setShowShareSheet] = useState(false)
  const [isConvertToPaylater, setIsConvertToPaylater] = useState(false)

  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{ completeDraftQuoteData = {} }, updateCompleteDraftQuoteReq] = useCompleteDraftQuote()
  const [{ completeDraftQuoteStatusCode, completeDraftQuoteErrorData }] = useErrorContextValue()
  const [{ COMPLETE_DRAFT_QUOTE_LOADER }, dispatchLoader] = useLoaderContextValue()

  useEffect(() => {
    getDraftQuoteDetailsReq({ draftQuoteId: id })
  }, [getDraftQuoteDetailsReq, id])

  useEffect(() => {
    if (completeDraftQuoteStatusCode === 400) {
      ShowSnackbar.error({
        text: completeDraftQuoteErrorData || ERROR_LANG.generalErrorTryAgain,
      })
    }
  }, [completeDraftQuoteStatusCode, completeDraftQuoteErrorData])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          COMPLETE_DRAFT_QUOTE_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (completeDraftQuoteData.id) {
      if (isConvertToPaylater) {
        history.push(`/transaction/type/${completeDraftQuoteData.id}`)
      } else {
        history.push(`/payment/car-protection/${completeDraftQuoteData.id}`)
      }
    }
  }, [history, completeDraftQuoteData, isConvertToPaylater])

  const { add_on, ...data } = draftQuotationsDetailsData?.policy_details?.addons_data || {}

  useEffect(() => {
    if (
      draftQuotationsDetailsData &&
      typeof draftQuotationsDetailsData === 'object' &&
      !Array.isArray(draftQuotationsDetailsData) &&
      Object.keys(draftQuotationsDetailsData).length > 0
    ) {
      updateDraftQuoteReq({
        body: {
          section: 'mv_quote_summary',
          sub_section: 'mv_quote_summary',
          data: {
            ...draftQuotationsDetailsData.policy_details,
            ...data,
            add_on: draftQuotationsDetailsData?.policy_details?.addons_data?.add_on || [],
            accessories_premium:
              draftQuotationsDetailsData?.policy_details?.package_data?.accessories_premium,
            accessories_sum_insured:
              draftQuotationsDetailsData?.policy_details?.package_data?.accessories_sum_insured,
            add_on_premium:
              draftQuotationsDetailsData?.policy_details?.package_data?.add_on_premium,
            basic_premium: draftQuotationsDetailsData?.policy_details?.package_data?.basic_premium,
            admin_fee: draftQuotationsDetailsData?.policy_details?.package_data?.admin_fee,
            allow_paylater:
              draftQuotationsDetailsData?.policy_details?.package_data?.allow_paylater,
            always_charge_hard_copy:
              draftQuotationsDetailsData?.policy_details?.package_data?.always_charge_hard_copy,
            applicable_period:
              draftQuotationsDetailsData?.policy_details?.package_data?.applicable_period,
            approve_without_details:
              draftQuotationsDetailsData?.policy_details?.package_data?.approve_without_details,
            discount_percentage:
              draftQuotationsDetailsData?.policy_details?.package_data?.discount_percentage,
            document_url_use_api:
              draftQuotationsDetailsData?.policy_details?.package_data?.document_url_use_api,
            max_discount: draftQuotationsDetailsData?.policy_details?.package_data?.max_discount,
            stamp_duty: draftQuotationsDetailsData?.policy_details?.package_data?.stamp_duty,
            start_policy_state:
              draftQuotationsDetailsData?.policy_details?.package_data?.start_policy_state,
            sub_total: draftQuotationsDetailsData?.policy_details?.package_data?.sub_total,
            total_bill: draftQuotationsDetailsData?.policy_details?.package_data?.total_bill,
            transmission_type: draftQuotationsDetailsData?.policy_details?.transmission_type,
          },
        },
        draftQuoteId: id,
      })
    }
  }, [draftQuotationsDetailsData, id, updateDraftQuoteReq])

  const handleCompleteDraft = () => {
    if (COMPLETE_DRAFT_QUOTE_LOADER === undefined) {
      updateCompleteDraftQuoteReq({
        draftQuoteId: id,
      })
    }
  }

  return (
    <Container
      title={'Asuransi Mobil'}
      showInnerHeader
      showCloseIcon
      displayBackButton
      hideBottomTabs
      onClose={() => history.replace('/dashboard')}
      onBackClick={() => history.push(`/motor_vehicle/customer/data/form/${id}`)}
    >
      <PolicyStepsHeader
        stepsData={POLICY_STEPS}
        activeCount={5}
        prevActive={{
          1: true,
          2: true,
          3: true,
          4: true,
        }}
      />
      <ConfirmationStyle>
        {draftQuotationsDetailsData?.policy_details?.package_code && (
          <PackageItem
            key={draftQuotationsDetailsData?.policy_details?.package_code}
            packageItem={{
              ...draftQuotationsDetailsData?.policy_details?.package_data,
              premium: draftQuotationsDetailsData?.policy_details?.premium,
            }}
            noCardClick
            purchaseType={draftQuotationsDetailsData?.policy_details?.purchase_type}
            applicationData={draftQuotationsDetailsData?.policy_details?.package_data}
          />
        )}

        <Tabs
          data={POLICY_TABS}
          defaultTab={activeTab}
          onClick={(tab) => setActiveTab(tab)}
          isSticky
          top="92px"
        />
        {activeTab.value === 'insurance' && (
          <TabInsuranceDetail id={id} draftQuotationsDetailsData={draftQuotationsDetailsData} />
        )}
        {activeTab.value === 'insured' && (
          <TabInsuredDetail draftQuotationsDetailsData={draftQuotationsDetailsData} />
        )}
        {activeTab.value === 'policy' && (
          <TabPolicyDetail draftQuotationsDetailsData={draftQuotationsDetailsData} />
        )}
        <MvPaymentInfo
          policyDetails={draftQuotationsDetailsData?.policy_details}
          onShareClick={() => setShowShareSheet(true)}
          onBuyClick={() => setShowPopupDisclaimer(true)}
          isShowConvertToPaylater={true}
          isConvertToPaylaterChecked={isConvertToPaylater}
          onConvertToPaylaterClick={() => setIsConvertToPaylater(!isConvertToPaylater)}
        />
      </ConfirmationStyle>

      {showPopupDisclaimer && (
        <PopupDisclaimer
          show={showPopupDisclaimer}
          onConfirmClick={handleCompleteDraft}
          onClose={() => setShowPopupDisclaimer(false)}
        />
      )}
      {showShareSheet && (
        <ShareQuotation
          draftId={id}
          show={showShareSheet}
          onClose={() => setShowShareSheet(false)}
        />
      )}
    </Container>
  )
}

export default MVPolicyConfirmationContainer
